class Solution { public String maskPII(String s){if(s.indexOf('@')>=0){String lower=s.toLowerCase();int at=lower.indexOf('@');return lower.charAt(0)+"*****"+lower.charAt(at-1)+lower.substring(at);}String digits=s.replaceAll("\\D","");int country=digits.length()-10;StringBuilder answer=new StringBuilder();if(country>0)answer.append('+').append("*".repeat(country)).append('-');answer.append("***-***-").append(digits.substring(digits.length()-4));return answer.toString();} }
